async (page) => {
  const root = 'http://127.0.0.1:8788/console-next/?v=knowledge-ux-20261014';
  page.setDefaultTimeout(6000);
  const completed = [];
  const errors = [];
  page.on('pageerror', error => errors.push(error.message));
  const verify = (condition, message) => { if (!condition) throw new Error(message); };
  const step = async (name, work) => { await work(); completed.push(name); };
  const nav = async name => page.locator(`.sidebar [data-page="${name}"]`).click();
  const submit = async name => page.locator(`form[data-form="${name}"] button[type="submit"]`).click();
  const openCollection = async name => {
    const opener = page.locator(`[data-action="collection-open"][data-page="${name}"]`).first();
    if (await opener.count()) await opener.click();
  };
  const openForm = async name => {
    const parent = page.locator(`form[data-form="${name}"]`).locator('xpath=..');
    const summary = parent.locator(':scope > summary');
    if (await summary.count()) await summary.click();
  };
  const reveal = async locator => {
    for (const detail of await locator.locator('xpath=ancestor::details').all()) {
      if (await detail.getAttribute('open') === null) await detail.locator(':scope > summary').click();
    }
  };
  const state = () => page.evaluate(() => window.__loomriseDemo.store.state);
  await page.route('**/console-next/**', route => route.continue());
  await page.setViewportSize({ width: 1440, height: 900 });
  await page.goto(root); await page.reload();
  await Promise.all([page.waitForEvent('load'), page.evaluate(() => window.__loomriseDemo.reset())]);
  await page.waitForFunction(() => window.__loomriseDemo?.store.state.ui.page === 'agents');

  await step('手动创建、切换助手入口保留输入、无需写工具', async () => {
    await page.getByRole('button', { name: '手动创建', exact: true }).click();
    await page.locator('form[data-form="create"] input[name="name"]').fill('网页售后客服');
    await page.locator('form[data-form="create"] textarea[name="goal"]').fill('根据有权使用的服务资料回答问题，复杂问题交人工。');
    await page.locator('[data-action="create-mode"][data-mode="assistant"]').click();
    verify(await page.locator('input[name="name"]').inputValue() === '网页售后客服', '切换创建方式丢失名称');
    await page.locator('[data-action="create-mode"][data-mode="manual"]').click();
    await submit('create');
    verify((await state()).ui.page === 'overview', '创建未进入业务概览');
    verify((await state()).ui.assistantOpen === false, '手动路径被强制打开助手');
  });
  const id = (await state()).selectedAgentId;
  await step('资料授权与分项处理、自己的FAQ可脚本试用', async () => {
    await nav('knowledge');
    await page.getByRole('button', { name: '添加资料', exact: true }).click();
    const form = page.locator('form[data-form="source"]');
    await form.locator('[name="title"]').fill('服务时间');
    await form.locator('[name="question"]').fill('周末可以咨询吗？');
    await form.locator('[name="answer"]').fill('周末上午九点到十二点提供人工咨询。');
    await form.locator('[name="sourceRef"]').fill('fictional:authorized-support-hours');
    await form.locator('[name="expires"]').fill('2099-12-31');
    await form.locator('[name="rights"]').check();
    await submit('source');
    await page.locator('[data-action="source-stage"][data-stage="parsed"]').click();
    await page.locator('[data-action="source-stage"][data-stage="review"]').click();
    await page.locator('[data-action="source-stage"][data-stage="indexed"]').click();
    await nav('trial');
    await page.locator('[name="question"]').fill('周末可以咨询吗？');
    await submit('trial');
    await page.getByText('周末上午九点到十二点提供人工咨询。', { exact: true }).waitFor();
    verify((await state()).runs[0].sources.length === 1, '脚本答复未留下资料引用');
  });
  await step('取消不追加迟到答复，未知与人工请求分开', async () => {
    await page.locator('[name="question"]').fill('取消这次测试');
    await submit('trial');
    await page.locator('[data-action="trial-cancel"]').click();
    await page.waitForTimeout(650);
    verify((await state()).ui.trialState === 'cancelled', '取消后状态被迟到答复覆盖');
    await page.locator('[data-action="trial-example"][data-kind="unknown"]').click();
    await submit('trial');
    await page.waitForFunction(() => window.__loomriseDemo.store.state.ui.trialState === 'complete');
    verify((await state()).runs[0].status === 'unknown', '资料外问题被当成解决');
    await page.locator('[data-action="trial-example"][data-kind="handoff"]').click();
    await submit('trial');
    await page.waitForFunction(() => window.__loomriseDemo.store.state.ui.trialState === 'complete');
    verify((await state()).runs[0].status === 'handoff', '转人工未区分请求状态');
  });
  await step('完整详细配置：字段、流程、策略和模拟工具', async () => {
    await nav('configuration');
    await page.locator('.depth-tabs [data-depth="detailed"]').click();
    await page.locator('[data-action="set-section"][data-section="fields"]').first().click();
    await openForm('field');
    const form = page.locator('form[data-form="field"]');
    await form.locator('[name="label"]').fill('联系电话');
    await form.getByText('自定义机器标识（可选）', { exact: true }).click();
    await form.locator('[name="id"]').fill('contact_phone');
    await submit('field');
    await page.locator('[data-bind="fields.0.label"]').fill('联系号码');
    await page.locator('[data-action="set-section"][data-section="flow"]').first().click();
    await openForm('flow');
    const flow = page.locator('form[data-form="flow"]');
    await flow.locator('[name="title"]').fill('确认是否需要人工');
    await flow.locator('[name="instruction"]').fill('先征求用户意愿，不把通知当成承接。');
    await submit('flow');
    await page.locator('[data-action="set-section"][data-section="tools"]').first().click();
    await openForm('tool');
    const tool = page.locator('form[data-form="tool"]');
    await tool.locator('[name="title"]').fill('创建工单（模拟）');
    await tool.locator('[name="sideEffect"]').selectOption('write');
    await submit('tool');
    const agent = (await state()).agents.find(agent => agent.id === id);
    verify(agent.config.fields[0].label === '联系号码', '详细字段修改未进入同一草稿');
    verify(agent.config.tools[0].requiresConfirm, '写工具失去确认要求');
  });
  await step('可选Agent候选审阅、保护人工字段、回到人工配置', async () => {
    await page.locator('[data-action="set-section"][data-section="service"]').first().click();
    await page.locator('[data-bind="greeting"]').fill('这是我手动确定的欢迎语。');
    await page.locator('[data-action="toggle-assistant"]').first().click();
    const sample = page.locator('[data-action="assistant-generate"]');
    await reveal(sample);
    await sample.click();
    await page.waitForFunction(() => window.__loomriseDemo.store.state.ui.assistant.status === 'ready');
    const generated = (await state()).ui.assistant.suggestions;
    verify(generated.find(item => item.path === 'greeting').blocked, '助手未保护人工欢迎语');
    const allowed = generated.find(item => !item.blocked);
    await page.locator(`[data-action="assistant-accept"][data-id="${allowed.id}"]`).click();
    verify((await state()).agents.find(agent => agent.id === id).config.greeting === '这是我手动确定的欢迎语。', '采用其他建议覆盖了人工欢迎语');
    await page.locator('[data-action="toggle-assistant"]').first().click();
    await page.locator('[data-bind="tone"]').fill('亲切专业');
  });
  await step('刷新保留草稿，审批/冻结/入口绑定分开', async () => {
    await page.reload();
    verify((await state()).agents.find(agent => agent.id === id).config.greeting === '这是我手动确定的欢迎语。', '刷新丢失草稿');
    await nav('versions');
    await page.locator('[data-action="sandbox-check"]').click();
    await page.locator('[data-action="sandbox-approve"]').click();
    await page.locator('[data-action="sandbox-publish"][data-target="widget"]').click();
    const agent = (await state()).agents.find(agent => agent.id === id);
    verify(Boolean(agent.bindings.widget), '批准后未能显式绑定Widget');
    await page.locator('[data-action="version-preview"]').first().click();
    await page.locator('[data-action="set-section"][data-section="service"]').first().click();
    verify(await page.locator('[data-bind="greeting"]').isDisabled(), '历史版本仍可编辑');
    await page.locator('[data-action="readonly-toggle"]').first().click();
  });
  await step('案例提名、人工标注、候选比较与采用', async () => {
    await nav('runs');
    await openCollection('runs');
    const nomination = page.locator('[data-action="case-from-run"]').first();
    await reveal(nomination);
    await nomination.click();
    await nav('cases');
    await openCollection('cases');
    await page.locator('[data-action="case-edit"]').first().click();
    const form = page.locator('form[data-form="case"]');
    await form.locator('[name="must"]').fill('明确记录人工交接请求。');
    await form.locator('[name="forbid"]').fill('不得声称问题解决或取消业务。');
    await submit('case');
    await page.locator('[data-action="case-review"]').first().click();
    await page.locator('[data-action="case-evaluate"]').first().click();
    await nav('iterations');
    await page.locator('[data-action="proposal-create"]').first().click();
    const proposal = page.locator('form[data-form="proposal"]');
    await proposal.locator('[name="title"]').fill('完善资料外回复');
    await proposal.locator('[name="reason"]').fill('便于用户知道下一步。');
    await proposal.locator('[name="after"]').fill('现有资料不足以核实，我可以交给人工。');
    await submit('proposal');
    await page.locator('[data-action="proposal-evaluate"]').first().click();
    await page.locator('[data-action="proposal-apply"]').first().click();
    verify((await state()).proposals[0].status === 'applied', '候选未经过比较并进入草稿');
  });
  await step('人工Inbox接管、回复、释放不改变请求终态', async () => {
    await nav('inbox');
    await page.locator('[data-action="inbox-simulate"]').first().click();
    await page.locator('[data-action="inbox-handoff"]').click();
    await page.locator('form[data-form="inbox"] [name="message"]').fill('收到，我先帮你核实。');
    await submit('inbox');
    await page.getByText('收到，我先帮你核实。', { exact: true }).waitFor();
    await page.locator('[data-action="inbox-release"]').click();
    verify((await state()).agents.find(agent => agent.id === id).conversations[0].requestStatus === 'waiting', '接管错误改变业务终态');
  });
  await step('Widget实时预览、联系页块操作和安装分项诊断', async () => {
    await nav('widget');
    await page.locator('[data-bind="widget.title"]').fill('欢迎了解我们的服务');
    await page.locator('[data-action="widget-check"]').click();
    verify((await state()).ui.widgetChecks.length === 4, '安装诊断没有分项');
    await nav('contact');
    await page.locator('[data-action="contact-template"]').first().click();
    await page.locator('[data-action="contact-add-block"][data-type="text"]').click();
    const blocks = (await state()).agents.find(agent => agent.id === id).config.contact.blocks;
    verify(blocks.length > 1, '联系页未添加受约束块');
    await page.locator('[data-bind="contact.blocks.0.title"]').fill('服务介绍');
  });
  await step('云部署失败/重试/备份恢复均可操作且保持模拟', async () => {
    await nav('deployment');
    await page.locator('[data-action="deployment-next"]').click();
    await page.locator('[data-action="deployment-fail"]').click();
    await page.locator('[data-action="deployment-retry"]').click();
    for (let i = 0; i < 3; i++) await page.locator('[data-action="deployment-next"]').click();
    await page.locator('[data-action="deployment-backup"]').click();
    await page.locator('[data-action="deployment-restore"]').click();
    verify((await state()).ui.deployment.status === 'complete', '部署步骤未完整推进');
    verify((await state()).ui.deployment.restore.status === 'simulation', '恢复未保持模拟');
  });
  await step('小屏导航键盘关闭与三面板切换', async () => {
    await page.setViewportSize({ width: 390, height: 844 });
    await page.goto(`${root}#/configuration?agent=${id}`);
    await page.locator('.topbar [data-action="toggle-nav"]').click();
    await page.keyboard.press('Escape');
    verify((await state()).ui.navOpen === false, 'Escape没有关闭导航');
    await page.locator('.mobile-panel-tabs [data-panel="assistant"]').click();
    verify(await page.getByRole('heading', { name: '创作助手（后续接入）', exact: true }).isVisible(), '小屏未能打开可选创作助手说明');
    await page.locator('.mobile-panel-tabs [data-panel="editor"]').click();
    verify(await page.locator('.editor-main').first().isVisible(), '小屏无法返回编辑');
    verify(await page.evaluate(() => document.documentElement.scrollWidth <= innerWidth), '小屏出现页面横向溢出');
  });
  verify(errors.length === 0, `浏览器错误：${errors.join('; ')}`);
  return { completed, count: completed.length, errors, agentId: id, note: '真实浏览器交互；所有AI/发布/渠道/云结果仍为模拟。' };
}
